type agreementUsedFirstParagraphDiagnosticOwner = agreementUsedFootnoteOwner

// Each plain target belongs to one first paragraph of a used definition.
func agreementUsedFirstParagraphDiagnosticOwners(check *agreementNativeCheckSource, notes []agreementUsedFootnoteDeclaration) ([]agreementUsedFootnoteOwner, bool) {
	var owners []agreementUsedFootnoteOwner
	used := make(map[graph.Span]bool)
	for fi, field := range check.Fields {
		if !slices.Contains(field.Targets, "A") || field.Comment || field.Escaped {
			continue
		}
		candidate := agreementUsedFootnoteOwner{}
		found := false
		for ni := range notes {
			note := &notes[ni]
			if !note.Found || note.Parent != extast.KindFootnoteList.String() || note.Label == "" || note.Bounds.Parent == "" || note.Bounds.Span.Start < 0 || note.Bounds.Span.Stop <= note.Bounds.Span.Start || note.Bounds.Label.Start < note.Bounds.Span.Start || note.Bounds.Label.Stop > note.Bounds.Span.Stop || note.Bounds.Label.Stop <= note.Bounds.Label.Start || field.Span.Start < note.Bounds.Span.Start || field.Span.Stop > note.Bounds.Span.Stop {
				continue
			}
			for pi := range note.Paragraphs {
				paragraph := &note.Paragraphs[pi]
				if paragraph.Ordinal != 0 || paragraph.Kind != ast.KindParagraph.String() {
					continue
				}
				for li, line := range paragraph.Lines {
					if field.Span.Start < line.Start || field.Span.Stop > line.Stop {
						continue
					}
					if found {
						return nil, false
					}
					found = true
					candidate = agreementUsedFootnoteOwner{Field: fi, Note: ni, Node: note.Node, Label: note.Label, Paragraph: pi, Ordinal: paragraph.Ordinal, Line: li}
				}
			}
		}
		if !found {
			continue
		}
		if field.Code || field.Comment || field.Escaped || field.DefinitionOwner >= 0 || field.CodeOwner >= 0 || len(field.Targets) != 1 || field.Word != "[[A]]" || field.Span.Start < 0 || field.Span.Stop-field.Span.Start != 5 || used[field.Span] {
			return nil, false
		}

		used[field.Span] = true
		owners = append(owners, candidate)
	}
	return owners, len(owners) > 0
}

func agreementUsedFirstParagraphDiagnosticPrivate(body, target string, owners []agreementUsedFirstParagraphDiagnosticOwner, check *agreementNativeCheckSource) (string, []agreementMixedRename, bool) {
	if target != "A" || len(owners) == 0 || strings.Contains(body, "q") {
		return "", nil, false
	}
	physical, ok := agreementUsedFirstParagraphDiagnosticOwners(check, agreementUsedFootnoteReading(body))
	if !ok {
		return "", nil, false
	}
	private := []byte(body)
	var changes []agreementMixedRename
	seen := map[int]bool{}
	for _, owner := range owners {
		if owner.Field < 0 || owner.Field >= len(check.Fields) || seen[owner.Field] || !slices.Contains(physical, owner) {
			return "", nil, false
		}
		seen[owner.Field] = true
		f := check.Fields[owner.Field]
		if f.Span.Start < 0 || f.Span.Stop > len(body) || body[f.Span.Start:f.Span.Stop] != "[[A]]" {
			return "", nil, false
		}
		private[f.Span.Start+2] = 'q'
		changes = append(changes, agreementMixedRename{Field: owner.Field, Span: graph.Span{Start: f.Span.Start + 2, Stop: f.Span.Start + 3}, Old: "A", New: "q"})
	}
	return string(private), changes, true
}
func agreementUsedFirstParagraphDiagnosticProducers(t *testing.T, body, target string, native agreementNativeOwnerSource, check *agreementNativeCheckSource) (physicalFields, diagnosticFields []agreementUsedFirstParagraphDiagnosticOwner, targetChanges []agreementMixedRename, projectedBody string, valid bool) {
	t.Helper()
	tree := agreementNativeProseAddressTreeReading(body, nil)
	notes := agreementUsedFootnoteReading(body)
	physical, ok := agreementUsedFirstParagraphDiagnosticOwners(check, notes)
	if !ok {
		return nil, nil, nil, "", false
	}
	raw, page := agreementIsolatedPage(t, agreementCase{Body: body})
	parts, pok := agreementCodeWindowParts(raw.HTML)
	if !pok {
		return nil, nil, nil, "", false
	}
	var owners []agreementUsedFirstParagraphDiagnosticOwner
	var changes []agreementMixedRename
	whole := []byte(body)
	used := map[int]bool{}
	for _, owner := range physical {
		private, oneChanges, valid := agreementUsedFirstParagraphDiagnosticPrivate(body, target, []agreementUsedFirstParagraphDiagnosticOwner{owner}, check)
		if !valid {
			continue
		}
		pr, pp := agreementIsolatedPage(t, agreementCase{Body: private})
		privateParts, validParts := agreementCodeWindowParts(pr.HTML)
		if !validParts || !cmp.Equal(native, agreementNativeOwnerReading(private)) || !cmp.Equal(tree, agreementNativeProseAddressTreeReading(private, nil)) || raw.HTML != pr.HTML || !cmp.Equal(page, pp) || !cmp.Equal(parts, privateParts) || len(raw.Diagnostics) != len(pr.Diagnostics) {
			continue
		}
		index := -1
		unique := true
		for di := range raw.Diagnostics {
			if cmp.Equal(raw.Diagnostics[di], pr.Diagnostics[di]) {
				continue
			}
			if index >= 0 {
				unique = false
				break
			}
			index = di
		}
		if !unique || index < 0 || used[index] {
			continue
		}
		a, b := raw.Diagnostics[index], pr.Diagnostics[index]
		change := oneChanges[0]
		if a.Kind != render.DiagWikilinkBroken || a.Target != target || b.Target != change.New || a.Kind != b.Kind || a.Section != b.Section || a.Block != b.Block || b.Message != strings.ReplaceAll(a.Message, "\""+target+"\"", "\""+change.New+"\"") {
			continue
		}
		used[index] = true
		owners = append(owners, owner)
		changes = append(changes, change)
		copy(whole[change.Span.Start:change.Span.Stop], change.New)
	}
	return physical, owners, changes, string(whole), len(owners) > 0
}

// A discarded diagnostic moves with its physical target while public faces stay fixed.
func agreementUsedFirstParagraphDiagnosticSignedProjection(before, after []agreementFailure, page *agreementHTML, targets []string, selected *agreementFailure, fields int) bool {
	if selected == nil || fields < 1 || fields != selected.Multiplicity || selected.Tuple.Target == "" {
		return false
	}
	target := selected.Tuple.Target
	replacement := strings.Repeat("q", len(target))
	counts := map[string]int{}
	for _, name := range targets {
		counts[name]++
	}
	visible := map[string]int{}
	for _, citation := range page.Citations {
		if citation.SourceRole == "" && citation.Target != "" {
			visible[citation.Target]++
		}
	}
	if counts[target] < fields || counts[replacement] != 0 || visible[replacement] != 0 {
		return false
	}
	signed := func(name string, delta int) string {
		if delta == 0 {
			return ""
		}
		direction := "judge-only"
		if delta < 0 {
			direction = "page-only"
			delta = -delta
		}
		f := agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: name}, Direction: direction, Multiplicity: delta}
		return agreementSignature(&f)
	}
	oldP1 := map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property == "P1" && (f.Tuple.Target == target || f.Tuple.Target == replacement) {
			oldP1[agreementSignature(f)]++
		}
	}
	declared := map[string]int{}
	if signature := signed(target, counts[target]-visible[target]); signature != "" {
		declared[signature] = 1
	}
	if !maps.Equal(oldP1, declared) {
		return false
	}
	expected := maps.Clone(agreementMixedCurrent(before))
	signature := agreementSignature(selected)
	if expected[signature] != 1 {
		return false
	}
	delete(expected, signature)
	renamed := *selected
	renamed.Tuple.Target = replacement
	expected[agreementSignature(&renamed)]++
	for key := range oldP1 {
		delete(expected, key)
	}
	if key := signed(target, counts[target]-fields-visible[target]); key != "" {
		expected[key]++
	}
	expected[signed(replacement, fields)]++
	return maps.Equal(expected, agreementMixedCurrent(after))
}

func agreementUsedFirstParagraphDiagnosticSource(body, target string) (*agreementUsedFirstParagraphDiagnosticSourceWitness, *agreementUsedFirstParagraphDiagnosticVariant, bool) {
	witnesses := agreementUsedFirstParagraphDiagnosticSources()
	for wi := range witnesses {
		w := &witnesses[wi]
		if w.Body != body {
			continue
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target == target {
				return w, v, true
			}
		}
		return nil, nil, false
	}
	return nil, nil, false
}

// Every changed diagnostic belongs to one declared first used paragraph field.
func agreementUsedFirstParagraphDiagnosticDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementUsedFirstParagraphDiagnosticWitnesses()
	for ri := range records {
		r := &records[ri]
		if c.Body != r.Body || f.Tuple.Target != r.Target {
			continue
		}
		if agreementSignature(f) != r.Selected || !cmp.Equal(diagnostics, r.Diagnostics) {
			return "", "", ""
		}
		w, v, found := agreementUsedFirstParagraphDiagnosticSource(c.Body, r.Target)
		if !found {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		notes := agreementUsedFootnoteReading(c.Body)
		parts, pok := agreementCodeWindowParts(raw)
		physical, ok := agreementUsedFirstParagraphDiagnosticOwners(&check, notes)
		private, changes, valid := agreementUsedFirstParagraphDiagnosticPrivate(c.Body, r.Target, v.Owners, &check)
		if !pok || !ok || !valid || len(v.Owners) != f.Multiplicity || len(r.Indices) != len(v.Owners) || !cmp.Equal(physical, v.Physical) || !cmp.Equal(changes, v.Changes) || private != v.Body || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(notes, w.Notes) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

